using System;
using System.Collections.Generic;
using System.Linq;
using HabitatShift.Core;
namespace HabitatShift.LevelLabR10 { public static class R10Validator {
 static R10Finding F(string s,string c,string d){return new R10Finding{severity=s,code=c,detail=d};}
 public static R10Report Check(R10Project p) { R10Storage.ValidateProject(p);var l=p.level;var r=new R10Report{playable=l.playableMask==null||l.playableMask.Length==0?l.cols*l.rows:l.playableMask.Length,habitats=l.habitats?.Length??0,initialTargets=l.targets?.Length??0,queued=(l.elevators??new ElevatorDto[0]).Sum(x=>x.queue?.Length??0),obstacles=l.obstacles?.Length??0};r.stages=(l.habitats??new HabitatDto[0]).Sum(x=>x.stages==null||x.stages.Length==0?1:x.stages.Length);r.density=r.playable==0?0:((l.habitats??new HabitatDto[0]).Sum(x=>x.shape?.Length??0)+r.initialTargets+r.obstacles)/(float)r.playable;
 if(l.cols<1||l.cols>10||l.rows<1||l.rows>10)r.findings.Add(F("FATAL","DIMENSIONS","Board must be 1..10."));foreach(var a in LevelV5Audit.Check(l))r.findings.Add(F(Severity(a.code),a.code,a.detail));var cycle=HasDependencyCycle(p.dependencyGraph);if(cycle){r.findings.Add(F("FATAL","DEPENDENCY_CYCLE","Dependency graph contains a cycle."));r.dependencyDepth=0;}else r.dependencyDepth=Depth(p.dependencyGraph);return r; }
 public static string Severity(string code) { switch(code ?? "") { case "DUPLICATE_TARGET_POSITION": case "PROVEN_QUEUE_STAGE_BLOCKER": case "SCHEMA": case "MASK": case "PLACEMENT": case "STAGES": case "SUPPLY": case "INVALID_ELEVATOR_ENTRY": case "INVALID_FOOTPRINT": case "OVERLAP": return "FATAL"; } if((code??"").Contains("SCHEMA")||(code??"").Contains("MASK")||(code??"").Contains("PLACEMENT")||(code??"").Contains("STAGE")||(code??"").Contains("SUPPLY")||(code??"").Contains("DUPLICATE")||(code??"").Contains("OUTSIDE")||(code??"").Contains("OVERLAP")||(code??"").Contains("INVALID")) return "FATAL"; if((code??"").Contains("MOBILITY")||(code??"").Contains("REACHABILITY")||(code??"").Contains("SEARCH_LIMIT")) return "WARNING"; return "WARNING"; }
 public static bool HasDependencyCycle(List<R10Edge> edges){var e=edges??new List<R10Edge>();var state=new Dictionary<string,int>();Func<string,bool> visit=null;visit=n=>{int v;if(state.TryGetValue(n,out v))return v==1;if(v==2)return false;state[n]=1;foreach(var x in e.Where(x=>x.from==n))if(visit(x.to))return true;state[n]=2;return false;};return e.SelectMany(x=>new[]{x.from,x.to}).Where(x=>!string.IsNullOrEmpty(x)).Any(visit);}
 public static int Depth(List<R10Edge> edges){var e=edges??new List<R10Edge>();if(HasDependencyCycle(e))return 0;var indegree=e.SelectMany(x=>new[]{x.from,x.to}).Distinct().ToDictionary(x=>x,x=>0);foreach(var x in e)indegree[x.to]++;var q=new Queue<string>(indegree.Where(x=>x.Value==0).Select(x=>x.Key));var depth=indegree.Keys.ToDictionary(x=>x,x=>0);while(q.Count>0){var n=q.Dequeue();foreach(var x in e.Where(x=>x.from==n)){depth[x.to]=Math.Max(depth[x.to],depth[n]+1);if(--indegree[x.to]==0)q.Enqueue(x.to);}}return depth.Count==0?0:depth.Values.Max();}
} }
#endif